$out['samples']=[];foreach(['news','research','papers'] as $stream){$rows=$s->db->get_results($s->db->prepare("SELECT i.id,i.source,i.canonical_url,i.published,i.priority,i.reasons,i.payload,d.topic_id FROM {$p}items i JOIN {$p}discovery d ON d.item_id=i.id WHERE d.stream=%s ORDER BY i.id DESC LIMIT 2",$stream),ARRAY_A);foreach($rows as &$row){$r=json_decode($row['payload'],true);$row['title']=$r['original_title'];$row['categories']=$r['categories'];$row['paper']=$r['paper']?array_diff_key($r['paper'],['abstract'=>1]):null;$row['reasons']=json_decode($row['reasons'],true);unset($row['payload']);}unset($row);$out['samples'][$stream]=$rows;}
